# %% pts/tests/06_net/test_net.pct.py 47
def test_context_full_workflow():
    """Test a complete workflow with create, consume, load, and send."""
    ctx = NodeExecutionContext(
        epoch_id="epoch_workflow",
        node_name="WorkflowNode",
    )

    # Set up input packet
    ctx._input_packet_values["input_pkt"] = {"input": "data"}

    # Consume input
    input_value = ctx.consume_packet("input_pkt")
    assert input_value == {"input": "data"}

    # Create output packet
    output_id = ctx.create_packet({"output": "result"})
    assert output_id.startswith("deferred_")

    # Load into output port
    ctx.load_output_port("out", output_id)

    # Send salvo
    ctx.send_output_salvo("send")

    # Check all actions queued correctly
    assert len(ctx._deferred_actions.actions) == 4
    action_types = [a[0] for a in ctx._deferred_actions.actions]
    assert action_types == ["consume_packet", "create_packet", "load_output_port", "send_output_salvo"]

    # Get execution result
    result = ctx._get_execution_result()
    assert not result.cancelled
    assert "input_pkt" in result.consumed_packets
    assert output_id in result.created_packets

# %% pts/tests/06_net/test_net.pct.py 50
def test_check_type_string_simple():
    """Test string-based type checking with simple type names."""
    ctx = NodeExecutionContext(epoch_id="test", node_name="Test")

    # Simple type names use __name__ matching
    name, matches, mode = ctx._check_type("int", 42)
    assert name == "int"
    assert matches is True
    assert mode == "string"

    name, matches, mode = ctx._check_type("str", "hello")
    assert name == "str"
    assert matches is True
    assert mode == "string"

    name, matches, mode = ctx._check_type("list", [1, 2, 3])
    assert name == "list"
    assert matches is True
    assert mode == "string"

    # Mismatches
    name, matches, mode = ctx._check_type("int", "not an int")
    assert name == "int"
    assert matches is False
    assert mode == "string"

# %% pts/tests/06_net/test_net.pct.py 52
def test_check_type_string_generic_fails():
    """Test that string generic types like 'list[int]' fail with __name__ matching.

    This is expected behavior - string mode uses __name__ which is just 'list',
    not 'list[int]'. For proper generic checking, use actual type objects.
    """
    ctx = NodeExecutionContext(epoch_id="test", node_name="Test")

    # String "list[int]" will NOT match because type([1,2,3]).__name__ is "list"
    name, matches, mode = ctx._check_type("list[int]", [1, 2, 3])
    assert name == "list[int]"
    assert matches is False  # Expected! __name__ is "list", not "list[int]"
    assert mode == "string"

